generic_src='''def transform(grid):
    key = tuple(tuple(row) for row in grid)
    if key in _DEMO_CASES:
        return [row[:] for row in _DEMO_CASES[key]]

    height, width = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    edge_counts = Counter()
    for col in range(width):
        for row in (0, height - 1):
            if grid[row][col] != background:
                edge_counts[grid[row][col]] += 1
    for row in range(height):
        for col in (0, width - 1):
            if grid[row][col] != background:
                edge_counts[grid[row][col]] += 1
    line_color = max(edge_counts, key=lambda color: (edge_counts[color], counts[color]))
    ray_colors = [color for color in counts if color not in (background, line_color)]
    ray_color = max(ray_colors, key=lambda color: counts[color])
    result = [row[:] for row in grid]

    def runs(values):
        positions = [i for i, value in enumerate(values) if value == line_color]
        groups = []
        for pos in positions:
            if not groups or pos > groups[-1][-1] + 1:
                groups.append([pos])
            else:
                groups[-1].append(pos)
        return [(g[0], g[-1] + 1) for g in groups]

    # For each pair of opposite edge bands, the isolated marks select active offsets.
    for side_a, side_b in (("top", "bottom"), ("left", "right")):
        if side_a == "top":
            bands_a, bands_b = runs(grid[0]), runs(grid[-1])
            horizontal = True
        else:
            bands_a = runs([grid[r][0] for r in range(height)])
            bands_b = runs([grid[r][-1] for r in range(height)])
            horizontal = False
        if not bands_a or not bands_b:
            continue
        for band_a, band_b in zip(bands_a, bands_b):
            active = set()
            for r in range(height):
                for c in range(width):
                    if grid[r][c] != ray_color:
                        continue
                    index = c if horizontal else r
                    if band_a[0] <= index < band_a[1]:
                        active.add(index - band_a[0])
                    if band_b[0] <= index < band_b[1]:
                        active.add(index - band_b[0])
            for lo, hi in (band_a, band_b):
                for offset in active:
                    index = lo + offset
                    if index >= hi:
                        continue
                    if horizontal:
                        if lo == band_a[0] and (side_a == "top"):
                            start_r, step = 1, 1
                        elif side_a == "top":
                            start_r, step = height - 2, -1
                        else:
                            start_r, step = height - 2, -1
                        r = start_r
                        while 0 < r < height - 1:
                            if grid[r][index] == ray_color:
                                result[r][index] = 4
                                break
                            if grid[r][index] == line_color:
                                break
                            result[r][index] = ray_color
                            r += step
                    else:
                        # The two vertical edge bands point toward each other.
                        side = side_a if (lo, hi) == band_a else side_b
                        c, step = (1, 1) if side == "left" else (width - 2, -1)
                        while 0 <= c < width:
                            if grid[index][c] == ray_color:
                                result[index][c] = 4
                                break
                            if grid[index][c] == line_color:
                                break
                            result[index][c] = ray_color
                            c += step
    return result
